<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:10px}table{border-collapse:collapse;width:100%}td,th{padding:8px;border:1px solid #bbb;text-align:left}thead{display:table-header-group}tr{page-break-inside:avoid}</style></head><body><h1>{{ __('Monthly uptime report') }}: {{ $report['month'] }} (UTC)</h1><p>{{ __('UTC calendar months. Uptime uses measured seconds; unobserved time is not counted as uptime. Recorded maintenance windows are excluded from coverage.') }}</p><table><thead><tr><th>{{ __('Service') }}</th><th>{{ __('Uptime') }}</th><th>{{ __('Coverage') }}</th><th>{{ __('Up seconds') }}</th><th>{{ __('Down seconds') }}</th><th>{{ __('Excluded maintenance seconds') }}</th><th>{{ __('Unobserved seconds') }}</th></tr></thead><tbody>@foreach($report['rows'] as $row)<tr><td>{{ $row['name'] }}</td><td>{{ $row['uptime'] === null ? __('No data') : number_format($row['uptime'], 2).'%' }}</td><td>{{ $row['coverage'] === null ? __('No data') : number_format($row['coverage'], 2).'%' }}</td><td>{{ $row['up_seconds'] }}</td><td>{{ $row['down_seconds'] }}</td><td>{{ $row['excluded_seconds'] }}</td><td>{{ $row['unobserved_seconds'] }}</td></tr>@endforeach</tbody></table></body></html>
